<span class="line"><span style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;"> (param = :mu, coef = &quot;habitat: grassland&quot;, estimate = 0.546744398029094, lower = 0.24835203643241344, upper = 0.8451363828395108)</span></span>
